static_assert(sizeof(fg174m_native::shared<16,32>)==38016&&sizeof(fg174m_native::shared<16,128>)==93312,"MMA shared-memory layout mismatch");
int64_t fg174m_query(int64_t pp,int64_t k){auto*p=(const fg174m_packet*)(uintptr_t)pp;const auto&a=p->args;switch(k){case 0:return p->device;case 1:return a.H;case 2:return a.H_k;case 3:return a.n_tokens;case 4:return a.n_seqs;case 5:return a.rq3;case 6:return a.eligible;case 7:return(int64_t)(uintptr_t)a.state_out;case 8:return ggml_cuda_info().devices[p->device].cc;case 9:return ggml_cuda_info().devices[p->device].nsm;case 10:return ggml_cuda_info().devices[p->device].smpbo;case 11:return GGML_CUDA_MAX_DEVICES;case 12:return ampere_mma_available(ggml_cuda_info().devices[p->device].cc);default:GGML_ABORT("Invalid MMA query");}}
int64_t fg174m_cc(int64_t k){switch(k){case 0:return GGML_CUDA_CC_AMPERE_GA10X;case 1:return GGML_CUDA_CC_ADA_LOVELACE;case 2:return GGML_CUDA_CC_BLACKWELL;case 3:return GGML_CUDA_CC_DGX_SPARK;default:GGML_ABORT("Invalid MMA architecture constant");}}
static void fg174m_slot(int64_t dev,int64_t path){GGML_ASSERT(dev>=0&&dev<GGML_CUDA_MAX_DEVICES&&path>=1&&path<=3);}
