uint8_t fg174m_launch(int64_t pp){auto*p=(fg174s_packet*)(uintptr_t)pp;const auto&q=p->plan;auto&ctx=*(ggml_backend_cuda_context*)(uintptr_t)p->args[1];ggml_cuda_gdn_mma_args a{};a.q=(const float*)(uintptr_t)q.ptrs[0];a.k=(const float*)(uintptr_t)q.ptrs[1];a.v=(const float*)(uintptr_t)q.ptrs[2];a.g=(const float*)(uintptr_t)q.ptrs[3];a.beta=(const float*)(uintptr_t)q.ptrs[4];a.state=(const float*)(uintptr_t)q.ptrs[5];a.dst=(float*)(uintptr_t)q.ptrs[6];a.state_out=(float*)(uintptr_t)q.ptrs[7];a.H=q.iv[1];a.H_k=q.iv[18];a.n_tokens=q.iv[2];a.n_seqs=q.iv[3];a.rq3=q.iv[5];a.sq1=q.strides[0][1];a.sq2=q.strides[0][2];a.sq3=q.strides[0][3];a.sv1=q.strides[2][1];a.sv2=q.strides[2][2];a.sv3=q.strides[2][3];a.sb1=q.strides[4][1];a.sb2=q.strides[4][2];a.sb3=q.strides[4][3];a.scale=q.fv[0];a.eligible=q.iv[17]!=0;return fg174m_enter(ctx.device,a,ctx.stream());}
